{
  "items": [
    {
      "path": "computer_use.org.pc.list_windows",
      "name": "list_windows",
      "description": "Discover window metadata for free, even while paused: IDs, titles, app, workspace, geometry and revisions. Omit workspace (or use 0) for all workspaces. No pixels or input authority.",
      "integration": "computer_use",
      "score": 303
    },
    {
      "path": "computer_use.org.pc.input_window",
      "name": "input_window",
      "description": "Perform up to 128 fully prevalidated window-scoped actions with a 60-second execution budget. Unicode text is limited to 262144 UTF-8 bytes per batch and delivered in 48-scalar chunks without clipboard access. Window-local logical coordinates and exact geometry revision required by default. Optional surface_id plus surface_revision from window_state selects surface-local coordinates, including popups. Pointer input hit-tests subsurfaces; crossing surfaces within a drag is refused. Input requires both agent-seat resources; unsupported clients and explicit focus actions are refused. No native-focus borrowing or global fallback. Runtime failures report acknowledged action/character counts; the failed transaction may still have effects, so re-observe before retrying. Optional then=state returns surface/dialog metadata; then=screenshot returns a permission-checked capture (optional observation crop/max_width/max_height) only after a completed batch. Set observation.delay_ms (0–5000, default 0) to wait before capture: applications may not have rendered when input completes; a delay is not a settled-frame guarantee. Observation failure never means replay the batch.",
      "integration": "computer_use",
      "score": 278
    },
    {
      "path": "computer_use.org.pc.view_window",
      "name": "view_window",
      "description": "Capture this actual toplevel only, never a desktop crop. Requires observation permission. Returns PNG, actual image dimensions, image-to-window transform, geometry revision, content frame ID and capture completion timestamp. Optional region crops the full-resolution toplevel before resizing (up to 4x zoom); max_width/max_height preserve aspect ratio. Crop transforms include offsets. Frame IDs are not input freshness tokens.",
      "integration": "computer_use",
      "score": 190
    },
    {
      "path": "computer_use.org.pc.window_state",
      "name": "window_state",
      "description": "Discover bounded compositor-owned popup/subsurface geometry and explicit transient-parent/child window IDs. Metadata only: no pixels, semantic contents or grants. Input to a new toplevel needs a separate grant. Use surface_id and its revision for popup-local input; active seat grabs remain refused.",
      "integration": "computer_use",
      "score": 190
    },
    {
      "path": "computer_use.org.pc.launch_application",
      "name": "launch_application",
      "description": "Launch an allowlisted application: chromium or pinta. Optional http(s) URL for Chromium only. New windows do not inherit input permission.",
      "integration": "computer_use",
      "score": 80
    }
  ],
  "total": 5,
  "hasMore": false,
  "nextOffset": null
}

